/// <summary>
/// Provides web search and page-fetching capabilities to the agent.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new();

    [Description("Search the web for a query and return a list of result snippets with URLs. Use this to find information on a topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        // Use DuckDuckGo Instant Answer API (no key required).
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

        using var response = await s_http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        var sb = new StringBuilder();

        // Abstract (main answer)
        var abs = root.GetProperty("Abstract").GetString();
        if (!string.IsNullOrWhiteSpace(abs))
        {
            var src = root.GetProperty("AbstractSource").GetString();
            var absUrl = root.GetProperty("AbstractURL").GetString();
            sb.AppendLine($"## {src}");
            sb.AppendLine(abs);
            sb.AppendLine($"URL: {absUrl}");
            sb.AppendLine();
        }

        // Related topics
        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            int count = 0;
            foreach (var topic in topics.EnumerateArray())
            {
                if (count >= 8) break;
                var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                {
                    sb.AppendLine($"- {text}");
                    if (!string.IsNullOrWhiteSpace(link))
                        sb.AppendLine($"  URL: {link}");
                    count++;
                }
            }
        }

        var result = sb.ToString();
        return string.IsNullOrWhiteSpace(result)
            ? $"No instant results found for \"{query}\". Try rephrasing the query."
            : result;
    }

    [Description("Fetch the text content of a web page given its URL. Use this to read a specific page found via search.")]
    public static async Task<string> FetchPage(
        [Description("The full URL to fetch")] string url)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

        using var response = await s_http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync();

        // Rough HTML-to-text: strip tags and limit length.
        var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();

        const int maxLen = 6000;
        if (text.Length > maxLen)
            text = text[..maxLen] + "\n... (truncated)";

        return text;
    }
}

/// <summary>
/// In-memory notebook that lets the agent save and recall findings.
/// </summary>
static class NoteTool
{
    private static readonly List<(string Title, string Content)> s_notes = [];

    [Description("Save a research note. Use this to record key findings, facts, or quotes as you discover them.")]
    public static string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content")] string content)
    {
        s_notes.Add((title, content));
        return $"Note #{s_notes.Count} saved: \"{title}\"";
    }

    [Description("List all saved research notes.")]
    public static string ListNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < s_notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {s_notes[i].Title}: {s_notes[i].Content}");
        return sb.ToString();
    }
}

