1. using System.ComponentModel;
2. using System.Net;
3. using System.Text;
4. using System.Text.Json;
5. using Microsoft.Agents.AI;
6. using Microsoft.Extensions.AI;
7. using OpenAI;
8. 
9. Console.WriteLine("🔬 Research Agent");
10. Console.WriteLine(new string('─', 50));
11. 
12. // Resolve the OpenAI-compatible endpoint.
13. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
14.     ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY");
15. var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL")
16.     ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT");
17. var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
18. 
19. if (string.IsNullOrEmpty(apiKey))
20. {
21.     Console.Error.WriteLine("Set OPENAI_API_KEY (or AZURE_OPENAI_API_KEY) to run the agent.");
22.     return;
23. }
24. 
25. // Build the IChatClient
26. var credential = new System.ClientModel.ApiKeyCredential(apiKey);
27. var clientOptions = new OpenAIClientOptions();
28. if (!string.IsNullOrEmpty(endpoint))
29.     clientOptions.Endpoint = new Uri(endpoint);
30. 
31. IChatClient chatClient = new OpenAIClient(credential, clientOptions)
32.     .GetChatClient(modelId)
33.     .AsIChatClient();
34. 
35. // Build the agent with tools
36. var tools = new AITool[]
37. {
38.     AIFunctionFactory.Create(WebSearchTool.SearchWeb),
39.     AIFunctionFactory.Create(WebSearchTool.FetchPage),
40.     AIFunctionFactory.Create(NoteTool.SaveNote),
41.     AIFunctionFactory.Create(NoteTool.ListNotes),
42. };
43. 
44. var agent = new ChatClientAgent(
45.     chatClient,
46.     name: "ResearchAgent",
47.     description: "An AI agent that researches topics by searching the web and taking notes.",
48.     instructions: """
49.         You are a research assistant. When given a topic:
50.         1. Search the web to find relevant information.
51.         2. Fetch promising pages to get more detail if needed.
52.         3. Save key findings as notes using the note-taking tool.
53.         4. After gathering enough information, list your notes and produce a
54.            clear, well-structured summary with citations.
55.         Be thorough but concise. Cite your sources with URLs.
56.         """,
57.     tools: tools);
58. 
59. // Interactive loop
60. var session = await agent.CreateSessionAsync();
61. 
62. Console.WriteLine("Enter a research topic (or 'quit' to exit):\n");
63. 
64. while (true)
65. {
66.     Console.ForegroundColor = ConsoleColor.Cyan;
67.     Console.Write("Research> ");
68.     Console.ResetColor();
69. 
70.     var input = Console.ReadLine();
71.     if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
72.         break;
73. 
74.     Console.WriteLine("\n⏳ Researching...\n");
75. 
76.     try
77.     {
78.         await foreach (var update in agent.RunStreamingAsync(input, session))
79.         {
80.             if (!string.IsNullOrEmpty(update.Text))
81.             {
82.                 Console.Write(update.Text);
83.             }
84.         }
85.     }
86.     catch (Exception ex)
87.     {
88.         Console.ForegroundColor = ConsoleColor.Red;
89.         Console.Error.WriteLine($"\nError: {ex.Message}");
90.         Console.ResetColor();
91.     }
92. 
93.     Console.WriteLine("\n");
94. }
95. 
96. Console.WriteLine("Goodbye!");
97. 
98. // ---------------------------------------------------------------------------
99. // Tools
100. // ---------------------------------------------------------------------------
101. 
102. /// <summary>
103. /// Provides web search and page-fetching capabilities to the agent.
104. /// </summary>
105. static class WebSearchTool
106. {
107.     private static readonly HttpClient s_http = new();
108. 
109.     [Description("Search the web for a query and return a list of result snippets with URLs. Use this to find information on a topic.")]
110.     public static async Task<string> SearchWeb(
111.         [Description("The search query")] string query)
112.     {
113.         // Use DuckDuckGo Instant Answer API (no key required).
114.         var encoded = WebUtility.UrlEncode(query);
115.         var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
116. 
117.         using var request = new HttpRequestMessage(HttpMethod.Get, url);
118.         request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");
119. 
120.         using var response = await s_http.SendAsync(request);
121.         response.EnsureSuccessStatusCode();
122. 
123.         var json = await response.Content.ReadAsStringAsync();
124.         using var doc = JsonDocument.Parse(json);
125.         var root = doc.RootElement;
126. 
127.         var sb = new StringBuilder();
128. 
129.         // Abstract (main answer)
130.         var abs = root.GetProperty("Abstract").GetString();
131.         if (!string.IsNullOrWhiteSpace(abs))
132.         {
133.             var src = root.GetProperty("AbstractSource").GetString();
134.             var absUrl = root.GetProperty("AbstractURL").GetString();
135.             sb.AppendLine($"## {src}");
136.             sb.AppendLine(abs);
137.             sb.AppendLine($"URL: {absUrl}");
138.             sb.AppendLine();
139.         }
140. 
141.         // Related topics
142.         if (root.TryGetProperty("RelatedTopics", out var topics))
143.         {
144.             int count = 0;
145.             foreach (var topic in topics.EnumerateArray())
146.             {
147.                 if (count >= 8) break;
148.                 var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
149.                 var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
150.                 if (!string.IsNullOrWhiteSpace(text))
151.                 {
152.                     sb.AppendLine($"- {text}");
