     public static string ListNotes()
     {
         if (s_notes.Count == 0)
             return "No notes saved yet.";

         var sb = new StringBuilder();
         for (int i = 0; i < s_notes.Count; i++)
             sb.AppendLine($"[{i + 1}] {s_notes[i].Title}: {s_notes[i].Content}");
         return sb.ToString();
     }
 }
